import re
def parse_traceparent(value):
 if not isinstance(value,str) or not re.fullmatch(r'00-[0-9a-f]{32}-[0-9a-f]{16}-[0-9a-f]{2}',value):raise ValueError('invalid version 00 traceparent')
 _,trace,parent,flags=value.split('-')
 if trace=='0'*32 or parent=='0'*16:raise ValueError('zero identifier')
 return {'trace_id':trace,'parent_id':parent,'sampled':bool(int(flags,16)&1),'version':'00'}

